#[test]
fn spec_exposes_parameters_with_prefixed_names_enums_and_required() {
    let build = build_tools(
        &store_with(&[("users", schema_spec_document())]),
        &McpOptions::enabled(),
    );
    let schema = Value::Object(build.tools[0].input_schema.clone());
    assert_eq!(
        schema["properties"]["path_id"],
        json!({ "type": "string", "description": "path parameter: id" })
    );
    assert_eq!(
        schema["properties"]["query_status"]["enum"],
        json!(["active", "inactive"])
    );
    assert_eq!(schema["required"], json!(["path_id", "body"]));
}

#[test]
fn spec_resolves_ref_bodies_and_breaks_circular_references() {
    let build = build_tools(
        &store_with(&[("users", schema_spec_document())]),
        &McpOptions::enabled(),
    );
    let body = &build.tools[0].input_schema["properties"]["body"];
    assert_eq!(body["description"], "Payload");
    assert_eq!(body["properties"]["name"], json!({ "type": "string" }));
    assert_eq!(body["properties"]["friend"], json!({}));
}

#[test]
fn spec_omits_parameters_rejected_by_the_parameter_filter() {
    let calls = Arc::new(std::sync::Mutex::new(Vec::new()));
    let seen = Arc::clone(&calls);
    let options = McpOptions::enabled().with_parameter_filter(move |param, context| {
        if let Ok(mut seen) = seen.lock() {
            seen.push((
                param["name"].clone(),
                context.service_name.to_string(),
                context.path.to_string(),
                context.method.to_string(),
            ));
        }
        param["name"] != "status"
    });
    let build = build_tools(&store_with(&[("users", schema_spec_document())]), &options);
    let properties = &build.tools[0].input_schema["properties"];
    assert!(properties.get("query_status").is_none());
    assert!(properties.get("path_id").is_some());
    assert_eq!(
        calls.lock().expect("lock")[0],
        (
            json!("id"),
            "users".to_string(),
            "/users/{id}".to_string(),
            "get".to_string()
        )
    );
}

#[test]
fn spec_empty_schema_when_the_operation_is_missing_from_the_original_document() {
    let store = store_with(&[("users", spec_document(spec_operation()))]);
    // A newer document that cannot be built replaces the original document but not the
    // Routes (OAS-03).
    let broken = json!({
        "openapi": "3.0.0",
        "info": { "title": "users", "version": "2" },
        "paths": { "/x({id})": { "get": { "responses": {} } } }
    });
    assert!(store.apply("users", "http://users/doc", broken).is_err());
    let build = build_tools(&store, &McpOptions::enabled());
    assert_eq!(
        Value::Object(build.tools[0].input_schema.clone()),
        json!({ "type": "object", "properties": {}, "required": [] })
    );
}

fn resolve(document: &Value, schema: &Value) -> (Value, Vec<String>) {
    let mut builder = schema::SchemaBuilder::new(document);
    let resolved = builder.resolve(schema, &mut Default::default());
    (Value::Object(resolved), builder.warnings)
}

#[test]
fn spec_resolves_nested_array_item_refs() {
    let document = json!({ "components": { "schemas": { "item": { "type": "string" } } } });
    let (resolved, _) = resolve(
        &document,
        &json!({ "type": "array", "items": { "$ref": "#/components/schemas/item" } }),
    );
    assert_eq!(
        resolved,
        json!({ "type": "array", "items": { "type": "string" } })
    );
}

#[test]
fn spec_unresolvable_ref_is_empty() {
    let (resolved, _) = resolve(
        &json!({}),
        &json!({ "$ref": "#/components/schemas/missing" }),
    );
    assert_eq!(resolved, json!({}));
}

#[test]
fn spec_coerces_stringified_constructor_types() {
    let (resolved, warnings) = resolve(
        &json!({}),
        &json!({
            "type": "object",
            "properties": {
                "name": { "type": "function String() { [native code] }" },
                "age": { "type": "function Number() { [native code] }" },
                "active": { "type": "function Boolean() { [native code] }" },
                "weird": { "type": "function Whatever() { [native code] }", "description": "unknown" }
            }
        }),
    );
    assert_eq!(resolved["properties"]["name"], json!({ "type": "string" }));
    assert_eq!(resolved["properties"]["age"], json!({ "type": "number" }));
    assert_eq!(
        resolved["properties"]["active"],
        json!({ "type": "boolean" })
    );
    assert_eq!(
        resolved["properties"]["weird"],
        json!({ "description": "unknown" })
    );
    assert_eq!(
        warnings,
        [
            "Dropping unmappable schema type \"function Whatever() { [native code] }\" while building MCP input schema."
        ]
    );
}

#[test]
fn spec_coerces_stringified_constructor_parameter_types() {
    let operation = json!({
        "operationId": "UserController_show",
        "responses": {},
        "parameters": [{ "in": "path", "name": "id", "required": true, "schema": { "type": "function String() { [native code] }" } }]
    });
    let build = spec_build(&McpOptions::enabled(), operation);
    assert_eq!(
        build.tools[0].input_schema["properties"]["path_id"],
        json!({ "type": "string", "description": "path parameter: id" })
    );
}

/// MCP-11: type normalisation, including lists.
#[test]
fn normalize_schema_types() {
    let cases = [
        (json!("STRING"), Some(json!("string"))),
        (json!("Integer"), Some(json!("integer"))),
        (
            json!("function BigInt() { [native code] }"),
            Some(json!("number")),
        ),
        (json!("function Date() {}"), Some(json!("string"))),
        (json!("function Array() {}"), Some(json!("array"))),
        (json!("function Object() {}"), Some(json!("object"))),
        (json!(["String", "NULL"]), Some(json!(["string", "null"]))),
        (json!(["bogus"]), None),
        (json!([["string"]]), None),
        (json!("bogus"), None),
        (json!(42), None),
        (json!(null), None),
    ];
    for (input, expected) in cases {
        assert_eq!(normalize_schema_type(&input), expected, "{input}");
    }
}

/// MCP-08: long names are kept and warned about; duplicate names resolve to the first tool.
#[test]
fn long_names_warn_and_duplicates_resolve_to_the_first() {
    let document = json!({
        "openapi": "3.0.0",
        "info": { "title": "t", "version": "1" },
        "paths": {
            "/one": { "get": { "operationId": "dup", "description": "first", "responses": {} } },
            "/two": { "get": { "operationId": "dup", "description": "second", "responses": {} } },
            "/long": { "get": { "operationId": "x".repeat(70), "responses": {} } }
        }
    });
    let store = store_with(&[("s", document)]);
    let registry = ToolRegistry::new(Arc::clone(&store), Arc::new(McpOptions::enabled()));
    registry.refresh();
    assert_eq!(registry.tools().len(), 3);
    assert_eq!(
        registry.tool("s_dup").map(|t| t.description.clone()),
        Some("first".into())
    );
    let build = build_tools(&store, &McpOptions::enabled());
    assert_eq!(
        build.warnings,
        [format!(
            "MCP tool name \"s_{}\" is 72 characters, which exceeds the recommended maximum of 64.",
            "x".repeat(70)
        )]
    );
}

// ---------------------------------------------------------------------------------------------
// MCP-05: rebuilds

#[tokio::test]
async fn registry_rebuilds_after_readiness_and_periodically() {
    let store = Arc::new(DocumentStore::new(
        vec![UpstreamService::new(
            "users",
            "http://users/doc",
            "http://users",
        )],
        SecurityKeys::default(),
    ));
    let registry = Arc::new(ToolRegistry::new(
        Arc::clone(&store),
        Arc::new(McpOptions::enabled()),
    ));
    let _handle = registry.start_with_interval(Duration::from_millis(100));
    assert!(registry.tools().is_empty());
    store
        .apply("users", "http://users/doc", spec_document(spec_operation()))
        .expect("loads");
    store.mark_ready();
    let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
    while registry.tools().len() != 1 {
        assert!(tokio::time::Instant::now() < deadline, "first rebuild");
        tokio::time::sleep(Duration::from_millis(5)).await;
    }
    // A new Route appears at the next periodic rebuild, not immediately.
    let mut document = spec_document(spec_operation());
    document["paths"]["/health"] = json!({ "get": { "operationId": "health", "responses": {} } });
    store
        .apply("users", "http://users/doc", document)
        .expect("loads");
    assert_eq!(registry.tools().len(), 1);
    while registry.tools().len() != 2 {
        assert!(tokio::time::Instant::now() < deadline, "periodic rebuild");
        tokio::time::sleep(Duration::from_millis(5)).await;
    }
}

#[tokio::test]
async fn registry_rebuilds_periodically_even_when_never_ready() {
    let store = Arc::new(DocumentStore::new(
        vec![UpstreamService::new(
            "users",
            "http://users/doc",
            "http://users",
        )],
        SecurityKeys::default(),
    ));
    store
        .apply("users", "http://users/doc", spec_document(spec_operation()))
        .expect("loads");
    let registry = Arc::new(ToolRegistry::new(
        Arc::clone(&store),
        Arc::new(McpOptions::enabled()),
    ));
    let handle = registry.start_with_interval(Duration::from_millis(50));
    let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
    while registry.tools().is_empty() {
        assert!(tokio::time::Instant::now() < deadline);
        tokio::time::sleep(Duration::from_millis(5)).await;
    }
    drop(handle);
}

#[test]
fn refresh_interval_is_five_minutes() {
    assert_eq!(TOOL_REFRESH_INTERVAL, Duration::from_secs(300));
}

