// mcp-tool-executor.service.spec.ts and the executor end to end

fn spec_tool_store() -> Arc<DocumentStore> {
    let document = json!({
        "openapi": "3.0.0",
        "info": { "title": "users", "version": "1" },
        "paths": {
            "/users/{id}": { "get": { "operationId": "UserController_show", "responses": {} } },
            "/users": { "post": { "operationId": "UserController_create", "responses": {} } },
            "/health": { "get": { "operationId": "health", "responses": {} } }
        }
    });
    store_with(&[("users", document)])
}

fn executor_with(backend: Arc<RecordingBackend>, exclude: &[&str]) -> ToolExecutor {
    let registry = Arc::new(ToolRegistry::new(
        spec_tool_store(),
        Arc::new(McpOptions::enabled()),
    ));
    registry.refresh();
    ToolExecutor::new(
        registry,
        backend,
        exclude.iter().map(|s| s.to_string()).collect(),
    )
}

fn mcp_request(headers: &[(&str, &str)]) -> http::request::Parts {
    let mut builder = http::Request::post("/mcp");
    for (name, value) in headers {
        builder = builder.header(*name, *value);
    }
    builder.body(()).expect("request").into_parts().0
}

fn call_of(text: &str) -> UpstreamCall {
    build_upstream_call(
        RouteMethod::Get,
        "/users/{id}",
        &object(serde_json::from_str(text).expect("args")),
        &ProxyRequest::new(),
        &[],
    )
    .expect("call")
}

#[test]
fn spec_extract_substitutes_path_and_collects_query_header_body() {
    let mut proxy_request = ProxyRequest::new();
    proxy_request.add_header("authUserId", "123");
    let call = build_upstream_call(
        RouteMethod::Post,
        "/users/{id}",
        &object(json!({ "path_id": "42", "query_status": "active", "header_locale": "en", "body": { "name": "a" } })),
        &proxy_request,
        &[],
    )
    .expect("call");
    assert_eq!(call.path_and_query, "/users/42/?status=active");
    assert_eq!(
        call.headers,
        [
            ("content-type", "application/json"),
            ("locale", "en"),
            ("auth-user-id", "123")
        ]
        .map(|(n, v)| (n.to_string(), v.to_string()))
    );
    assert_eq!(call.body.as_deref(), Some(r#"{"name":"a"}"#));
}

#[test]
fn spec_appends_a_trailing_slash_and_ignores_unknown_arguments() {
    let call = build_upstream_call(
        RouteMethod::Get,
        "/health",
        &object(json!({ "unrelated": "x" })),
        &ProxyRequest::new(),
        &[],
    )
    .expect("call");
    assert_eq!(call.path_and_query, "/health/");
    assert_eq!(call.body, None);
    assert_eq!(call_of(r#"{"path_id":"1"}"#).path_and_query, "/users/1/");
}

#[test]
fn spec_never_lets_an_argument_supply_a_gateway_owned_header() {
    let mut proxy_request = ProxyRequest::new();
    proxy_request.add_header("authUserId", "trusted");
    let exclude = ["auth-user-id".to_string()];
    let call = build_upstream_call(
        RouteMethod::Get,
        "/users/{id}",
        &object(
            json!({ "path_id": "42", "header_auth-user-id": "spoofed", "header_locale": "en" }),
        ),
        &proxy_request,
        &exclude,
    )
    .expect("call");
    assert!(
        call.headers
            .contains(&("auth-user-id".into(), "trusted".into()))
    );
    assert!(call.headers.contains(&("locale".into(), "en".into())));
    let call = build_upstream_call(
        RouteMethod::Get,
        "/users/{id}",
        &object(json!({ "path_id": "42", "header_Auth-User-Id": "spoofed" })),
        &ProxyRequest::new(),
        &exclude,
    )
    .expect("call");
    assert!(
        !call
            .headers
            .iter()
            .any(|(n, _)| n.eq_ignore_ascii_case("auth-user-id"))
    );
}

#[test]
fn spec_serializes_the_body_only_for_post_put_patch() {
    let args = object(json!({ "body": { "name": "a" } }));
    for (method, sent) in [
        (RouteMethod::Post, true),
        (RouteMethod::Put, true),
        (RouteMethod::Patch, true),
        (RouteMethod::Get, false),
        (RouteMethod::Delete, false),
        (RouteMethod::Head, false),
    ] {
        let call =
            build_upstream_call(method, "/users", &args, &ProxyRequest::new(), &[]).expect("call");
        assert_eq!(call.body.is_some(), sent, "{method}");
    }
}

