#[tokio::test]
async fn spec_downstream_errors_and_client_failures() {
    let backend = RecordingBackend::new();
    let executor = executor_with(Arc::clone(&backend), &[]);
    backend.push_response(Ok(UpstreamResponse {
        status: 500,
        body: b"boom".to_vec(),
    }));
    let result = executor
        .call("users_health", &Map::new(), &mcp_request(&[]))
        .await;
    assert_eq!(
        result,
        ToolResult::error("Error executing users_health: Downstream service returned 500: boom")
    );
    backend.push_response(Ok(UpstreamResponse {
        status: 399,
        body: b"fine".to_vec(),
    }));
    assert_eq!(
        executor
            .call("users_health", &Map::new(), &mcp_request(&[]))
            .await,
        ToolResult::success("fine")
    );
    backend.push_response(Err(UpstreamError {
        message: "other side closed".into(),
    }));
    let result = executor
        .call("users_health", &Map::new(), &mcp_request(&[]))
        .await;
    assert_eq!(
        result,
        ToolResult::error("Error executing users_health: other side closed")
    );
    backend.push_response(Ok(UpstreamResponse {
        status: 200,
        body: vec![0x66, 0xff, 0x6f],
    }));
    let result = executor
        .call("users_health", &Map::new(), &mcp_request(&[]))
        .await;
    assert_eq!(result, ToolResult::success("f\u{fffd}o"));
}

