// ---------------------------------------------------------------------------------------------
// The endpoint, in process (MCP-01 to MCP-04 and the rmcp side of MCP-02)

fn endpoint(backend: Arc<RecordingBackend>, options: McpOptions) -> McpEndpoint {
    let registry = Arc::new(ToolRegistry::new(spec_tool_store(), Arc::new(options)));
    registry.refresh();
    let executor = Arc::new(ToolExecutor::new(
        registry,
        backend,
        vec!["auth-user-id".into()],
    ));
    McpEndpoint::new(executor, vec![Arc::new(HeaderAuthentication)])
}

struct Exchange {
    status: u16,
    content_type: Option<String>,
    session_id: bool,
    body: String,
}

impl Exchange {
    /// Every JSON-RPC message of an SSE or JSON body.
    fn messages(&self) -> Vec<Value> {
        if self
            .content_type
            .as_deref()
            .is_some_and(|c| c.starts_with("text/event-stream"))
        {
            self.body
                .lines()
                .filter_map(|l| l.strip_prefix("data:"))
                .filter_map(|d| serde_json::from_str(d.trim()).ok())
                .collect()
        } else {
            match serde_json::from_str(&self.body) {
                Ok(Value::Array(items)) => items,
                Ok(value) => vec![value],
                Err(_) => Vec::new(),
            }
        }
    }
}

async fn exchange(endpoint: &McpEndpoint, request: http::Request<Full<Bytes>>) -> Exchange {
    let response = endpoint.handle(request).await;
    let status = response.status().as_u16();
    let content_type = response
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .map(str::to_string);
    let session_id = response.headers().contains_key("mcp-session-id");
    // An SSE stream may stay open after the last message; read what arrives in time.
    let mut body = response.into_body();
    let mut bytes = Vec::new();
    while let Ok(Some(Ok(frame))) =
        tokio::time::timeout(Duration::from_millis(500), body.frame()).await
    {
        if let Ok(data) = frame.into_data() {
            bytes.extend_from_slice(&data);
        }
    }
    Exchange {
        status,
        content_type,
        session_id,
        body: String::from_utf8_lossy(&bytes).into_owned(),
    }
}

fn post(body: &str, headers: &[(&str, &str)]) -> http::Request<Full<Bytes>> {
    let mut builder = http::Request::post("/mcp").header("host", "127.0.0.1:4000");
    for (name, value) in headers {
        builder = builder.header(*name, *value);
    }
    builder
        .body(Full::new(Bytes::from(body.to_string())))
        .expect("request")
}

const ACCEPT: (&str, &str) = ("accept", "application/json, text/event-stream");
const JSON: (&str, &str) = ("content-type", "application/json");

fn rpc(method: &str, params: Value) -> String {
    json!({ "jsonrpc": "2.0", "id": 1, "method": method, "params": params }).to_string()
}

fn initialize(version: &str) -> String {
    rpc(
        "initialize",
        json!({ "protocolVersion": version, "capabilities": {}, "clientInfo": { "name": "t", "version": "1" } }),
    )
}

