/// MCP-04: authentication before any protocol handling.
#[tokio::test]
async fn endpoint_authentication() {
    let backend = RecordingBackend::new();
    let endpoint = endpoint(Arc::clone(&backend), McpOptions::enabled());
    let ping = rpc("ping", json!({}));

    let deny = exchange(&endpoint, post("{", &[("x-test-mcp-auth", "deny")])).await;
    assert_eq!(
        (deny.status, deny.body.as_str()),
        (401, r#"{"error":"Unauthorized"}"#)
    );
    assert_eq!(
        deny.content_type.as_deref(),
        Some("application/json; charset=utf-8")
    );

    let respond = exchange(
        &endpoint,
        post(&ping, &[ACCEPT, JSON, ("x-test-mcp-auth", "respond")]),
    )
    .await;
    assert_eq!(
        (respond.status, respond.body.as_str()),
        (418, r#"{"message":"test mcp authentication response"}"#)
    );

    let failed = exchange(
        &endpoint,
        post(&ping, &[ACCEPT, JSON, ("x-test-mcp-auth", "throw")]),
    )
    .await;
    assert_eq!(
        (failed.status, failed.body.as_str()),
        (
            500,
            r#"{"statusCode":500,"message":"Internal server error"}"#
        )
    );

    let call = rpc("tools/call", json!({ "name": "users_health" }));
    let denied = exchange(
        &endpoint,
        post(&call, &[ACCEPT, JSON, ("x-test-mcp-auth", "deny")]),
    )
    .await;
    assert_eq!(denied.status, 401);
    assert!(backend.authorized().is_empty());

    // Handlers run in order and stop at the first refusal.
    struct Counting(Arc<AtomicUsize>, McpAuthOutcomeKind);
    #[derive(Clone, Copy)]
    enum McpAuthOutcomeKind {
        Allow,
        Deny,
    }
    #[crate::handler::async_trait]
    impl McpAuthentication for Counting {
        async fn authenticate(
            &self,
            request: &mut crate::handler::GatewayRequest,
        ) -> Result<McpAuthDecision, crate::handler::MiddlewareError> {
            self.0.fetch_add(1, Ordering::SeqCst);
            request.extensions_mut().insert(42_u32);
            Ok(match self.1 {
                McpAuthOutcomeKind::Allow => McpAuthDecision::Allow,
                McpAuthOutcomeKind::Deny => McpAuthDecision::Deny,
            })
        }
    }
    let registry = Arc::new(ToolRegistry::new(
        spec_tool_store(),
        Arc::new(McpOptions::enabled()),
    ));
    let executor = Arc::new(ToolExecutor::new(
        registry,
        RecordingBackend::new(),
        Vec::new(),
    ));
    let (first, second, third) = (
        Arc::new(AtomicUsize::new(0)),
        Arc::new(AtomicUsize::new(0)),
        Arc::new(AtomicUsize::new(0)),
    );
    let endpoint = McpEndpoint::new(
        executor,
        vec![
            Arc::new(Counting(Arc::clone(&first), McpAuthOutcomeKind::Allow)),
            Arc::new(Counting(Arc::clone(&second), McpAuthOutcomeKind::Deny)),
            Arc::new(Counting(Arc::clone(&third), McpAuthOutcomeKind::Allow)),
        ],
    );
    assert_eq!(
        exchange(&endpoint, post(&ping, &[ACCEPT, JSON]))
            .await
            .status,
        401
    );
    assert_eq!(
        [
            first.load(Ordering::SeqCst),
            second.load(Ordering::SeqCst),
            third.load(Ordering::SeqCst)
        ],
        [1, 1, 0]
    );
}

/// MCP-02, the rmcp side: what `rmcp` 3.11 answers for each exchange of
/// `conformance::mcp::mcp_02_transport`. Exchanges where it differs from the reference's
/// TypeScript SDK are listed in `docs/parity/08-mcp.md` (MCP-02); this test pins rmcp's
/// behaviour so an upgrade that changes it is noticed.
#[tokio::test]
async fn endpoint_transport_behaviour_of_rmcp() {
    let endpoint = endpoint(RecordingBackend::new(), McpOptions::enabled());
    let ping = r#"{"jsonrpc":"2.0","id":1,"method":"ping"}"#;
    let cases: Vec<(&str, http::Request<Full<Bytes>>)> = vec![
        (
            "initialize 2025-06-18",
            post(&initialize("2025-06-18"), &[ACCEPT, JSON]),
        ),
        (
            "initialize 2024-11-05",
            post(&initialize("2024-11-05"), &[ACCEPT, JSON]),
        ),
        (
            "initialize unknown version",
            post(&initialize("1999-01-01"), &[ACCEPT, JSON]),
        ),
        ("ping", post(ping, &[ACCEPT, JSON])),
        (
            "notification",
            post(
                r#"{"jsonrpc":"2.0","method":"notifications/initialized"}"#,
                &[ACCEPT, JSON],
            ),
        ),
        (
            "client response",
            post(r#"{"jsonrpc":"2.0","id":5,"result":{}}"#, &[ACCEPT, JSON]),
        ),
        (
            "unknown method",
            post(
                r#"{"jsonrpc":"2.0","id":7,"method":"foo/bar","params":{}}"#,
                &[ACCEPT, JSON],
            ),
        ),
        (
            "resources/list",
            post(&rpc("resources/list", json!({})), &[ACCEPT, JSON]),
        ),
        ("malformed JSON", post(r#"{"jsonrpc":"#, &[ACCEPT, JSON])),
        ("empty body", post("", &[ACCEPT, JSON])),
        ("not JSON-RPC", post(r#"{"foo":1}"#, &[ACCEPT, JSON])),
        (
            "jsonrpc 1.0",
            post(
                r#"{"jsonrpc":"1.0","id":1,"method":"ping"}"#,
                &[ACCEPT, JSON],
            ),
        ),
        (
            "null id",
            post(
                r#"{"jsonrpc":"2.0","id":null,"method":"ping"}"#,
                &[ACCEPT, JSON],
            ),
        ),
        (
            "batch of requests",
            post(
                r#"[{"jsonrpc":"2.0","id":1,"method":"ping"},{"jsonrpc":"2.0","id":2,"method":"ping"}]"#,
                &[ACCEPT, JSON],
            ),
        ),
        ("empty batch", post("[]", &[ACCEPT, JSON])),
        ("no Accept", post(ping, &[JSON])),
        ("Accept */*", post(ping, &[("accept", "*/*"), JSON])),
        (
            "content-type text/plain",
            post(ping, &[ACCEPT, ("content-type", "text/plain")]),
        ),
        (
            "content-type with charset",
            post(
                ping,
                &[ACCEPT, ("content-type", "application/json; charset=utf-8")],
            ),
        ),
        (
            "unsupported mcp-protocol-version",
            post(
                ping,
                &[ACCEPT, JSON, ("mcp-protocol-version", "1999-01-01")],
            ),
        ),
        (
            "mcp-session-id header",
            post(ping, &[ACCEPT, JSON, ("mcp-session-id", "abc")]),
        ),
        (
            "tools/call without name",
            post(&rpc("tools/call", json!({})), &[ACCEPT, JSON]),
        ),
        (
            "tools/call with array arguments",
            post(
                &rpc(
                    "tools/call",
                    json!({ "name": "users_health", "arguments": [1] }),
                ),
                &[ACCEPT, JSON],
            ),
        ),
        (
            "initialize 2024-10-07",
            post(&initialize("2024-10-07"), &[ACCEPT, JSON]),
        ),
        (
            "initialize 2026-07-28",
            post(&initialize("2026-07-28"), &[ACCEPT, JSON]),
        ),
        (
            "mcp-protocol-version 2024-10-07",
            post(
                ping,
                &[ACCEPT, JSON, ("mcp-protocol-version", "2024-10-07")],
            ),
        ),
        (
            "mcp-protocol-version 2026-07-28",
            post(
                ping,
                &[ACCEPT, JSON, ("mcp-protocol-version", "2026-07-28")],
            ),
        ),
    ];
    let mut observed = Vec::new();
    for (label, request) in cases {
        let reply = exchange(&endpoint, request).await;
        let line = json!({
            "status": reply.status,
            "contentType": reply.content_type,
            "sessionId": reply.session_id,
            "messages": reply.messages(),
            "rawBody": if reply.messages().is_empty() { Value::String(reply.body.clone()) } else { Value::Null },
        });
        println!("{label}: {line}");
        observed.push((label, line));
    }
    let get = |label: &str| {
        observed
            .iter()
            .find(|(l, _)| *l == label)
            .map(|(_, v)| v.clone())
            .unwrap_or(Value::Null)
    };
    let messages = |label: &str| get(label)["messages"].clone();
    let raw = |label: &str| (get(label)["status"].clone(), get(label)["rawBody"].clone());

    // Shared with the reference.
    assert_eq!(get("ping")["status"], 200);
    assert_eq!(get("ping")["contentType"], "text/event-stream");
    assert_eq!(
        messages("ping"),
        json!([{ "jsonrpc": "2.0", "id": 1, "result": {} }])
    );
    assert_eq!(get("ping")["sessionId"], false);
    assert_eq!(get("mcp-session-id header")["status"], 200);
    assert_eq!(get("content-type with charset")["status"], 200);
    assert_eq!(raw("notification"), (json!(202), json!("")));
    for (label, version) in [
        ("initialize 2025-06-18", "2025-06-18"),
        ("initialize 2024-11-05", "2024-11-05"),
        ("initialize 2024-10-07", "2024-10-07"),
        ("initialize unknown version", "2025-11-25"),
        ("initialize 2026-07-28", "2025-11-25"),
    ] {
        assert_eq!(
            messages(label)[0]["result"]["protocolVersion"],
            version,
            "{label}"
        );
    }
    assert_eq!(
        messages("unknown method"),
        json!([{ "jsonrpc": "2.0", "id": 7, "error": { "code": -32601, "message": "Method not found" } }])
    );

    // Where rmcp differs from the reference (listed under MCP-02 in docs/parity/08-mcp.md).
    assert_eq!(
        messages("resources/list"),
        json!([{ "jsonrpc": "2.0", "id": 1, "error": { "code": -32601, "message": "resources/list" } }])
    );
    assert_eq!(
        messages("client response"),
        json!([{ "jsonrpc": "2.0", "error": { "code": -32600, "message": "stateless server does not accept JSON-RPC responses" } }])
    );
    assert_eq!(get("client response")["status"], 400);
    for label in [
        "malformed JSON",
        "empty body",
        "not JSON-RPC",
        "jsonrpc 1.0",
        "null id",
        "batch of requests",
        "empty batch",
    ] {
        let (status, body) = raw(label);
        assert_eq!(status, 415, "{label}");
        assert!(
            body.as_str()
                .is_some_and(|b| b.starts_with("fail to deserialize request body")),
            "{label}: {body}"
        );
    }
    assert_eq!(
        raw("no Accept"),
        (
            json!(406),
            json!("Not Acceptable: Client must accept both application/json and text/event-stream")
        )
    );
    assert_eq!(raw("Accept */*").0, 406);
    assert_eq!(
        raw("content-type text/plain"),
        (
            json!(415),
            json!("Unsupported Media Type: Content-Type must be application/json")
        )
    );
    assert_eq!(
        raw("unsupported mcp-protocol-version"),
        (
            json!(400),
            json!("Bad Request: Unsupported MCP-Protocol-Version: 1999-01-01")
        )
    );
    assert_eq!(
        raw("mcp-protocol-version 2024-10-07"),
        (
            json!(400),
            json!("Bad Request: Unsupported MCP-Protocol-Version: 2024-10-07")
        )
    );
    assert_eq!(get("mcp-protocol-version 2026-07-28")["status"], 400);
    assert_eq!(
        messages("mcp-protocol-version 2026-07-28")[0]["error"]["code"],
        -32020
    );
    for label in ["tools/call without name", "tools/call with array arguments"] {
        assert_eq!(messages(label)[0]["error"]["code"], -32601, "{label}");
    }

    // The SSE framing and headers: rmcp writes no `event:` line and `cache-control:
    // no-cache` (the reference: `event: message` and `no-cache, no-transform`).
    let response = endpoint.handle(post(ping, &[ACCEPT, JSON])).await;
    assert_eq!(
        response
            .headers()
            .get("cache-control")
            .and_then(|v| v.to_str().ok()),
        Some("no-cache")
    );
    let reply = exchange(&endpoint, post(ping, &[ACCEPT, JSON])).await;
    assert_eq!(
        reply.body,
        "data: {\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{}}\n\n"
    );
}
